VAR
    Current_Overload_Timer : TON;
END_VAR

// Evaluate fault conditions and control motor stop and overload alarm
IF Motor_Winding_Temp > 140.0 OR (Motor_Current > 51.9 AND Motor_Running) THEN
    Current_Overload_Timer(IN := TRUE, PT := T#3S);
ELSE
    Current_Overload_Timer(IN := FALSE, PT := T#3S);
END_IF;

// Latch or trigger stop and overload based on conditions
IF Motor_Winding_Temp > 140.0 OR Current_Overload_Timer.Q THEN
    Motor_Stop := TRUE;
    Overload_Alarm := TRUE;
ELSIF Fault_Reset THEN
    Motor_Stop := FALSE;
    Overload_Alarm := FALSE;
END_IF;

